sys_script.script:
(function executeRule(current, previous) {

    // Generate ticket when the inherited Task Approval field
    // changes to approved.
    if (!current.approval.changesTo('approved')) {
        return;
    }

    var ticketNumber =
        'HMR-' + current.getValue('number');

    current.setValue(
        'ticket_number',
        ticketNumber
    );

    var qrPayload = {

        ticketNumber:
            ticketNumber,

        bookingNumber:
            current.getValue('number'),

        requestedFor:
            current.getDisplayValue('requested_for'),

        source:
            current.getDisplayValue('source_station'),

        destination:
            current.getDisplayValue('destination_station'),

        travelDate:
            current.getValue('travel_date'),

        journeyType:
            current.getValue('journey_type'),

        passengers:
            current.getValue('passenger_count'),

        distanceKm:
            current.getValue('distance_km'),

        durationMinutes:
            current.getValue('duration_minutes'),

        totalFare:
            current.getValue('total_fare'),

        status:
            'generated'
    };

    current.setValue(
        'qr_data',
        JSON.stringify(qrPayload)
    );

    current.setValue(
        'generated_at',
        new GlideDateTime().getValue()
    );

    current.setValue(
        'metro_status',
        'generated'
    );

})(current, previous);
